for _ in range(int(input())):
	a = input()
	b = input()
	a_small = ''
	a_big = ''
	a_small1 = ''
	a_big1 = ''
	a = list(a)
	b = list(b)
	for i in range(len(b)):
		a.remove(b[i])
	a = ''.join(a)
	b = ''.join(b)
	for i in range(len(a)):
		if ord(a[i]) <= ord(b[0]):
			a_small += a[i]
		elif a[i]:
			a_big += a[i]
	ans = ''.join(sorted(a_small)) + b + ''.join(sorted(a_big))
	for i in range(len(a)):
		if ord(a[i]) < ord(b[0]):
			a_small1 += a[i]
		elif a[i]:
			a_big1 += a[i]
	ans1 = ''.join(sorted(a_small1)) + b + ''.join(sorted(a_big1))
	print(min(ans, ans1))
